mapper.select:
SELECT COUNT(*)
FROM (
    SELECT mr.patient_id, mr.dept_sub_id, mr.doctor_id
    FROM medical_registration mr
        LEFT JOIN patient_user_info pi ON mr.patient_id = pi.id
        LEFT JOIN doctor d ON mr.doctor_id = d.id
        LEFT JOIN medical_dept_sub mds ON mr.dept_sub_id = mds.id
        LEFT JOIN medical_dept md ON mds.dept_id = md.id
    WHERE 1 = 1

        AND pi.name LIKE CONCAT('%',#{name},'%')


        AND pi.sex = #{sex}


        AND md.id = #{deptId}


        AND mds.id = #{deptSubId}


        AND d.id = #{doctorId}


        AND mr.status = #{status}

    GROUP BY mr.patient_id, mr.dept_sub_id, mr.doctor_id
) t

SELECT mr.patient_id AS patientId, mr.dept_sub_id AS deptSubId, mr.doctor_id AS doctorId, MAX(pi.name) AS name, MAX(pi.sex) AS sex, MAX(md.name) AS deptName, MAX(mds.name) AS deptSubName, MAX(d.name) AS doctorName, (SELECT mr2.date FROM medical_registration mr2 WHERE mr2.patient_id = mr.patient_id AND mr2.dept_sub_id = mr.dept_sub_id AND mr2.doctor_id = mr.doctor_id ORDER BY mr2.status ASC, mr2.create_time DESC LIMIT 1) AS date, (SELECT mr2.slot FROM medical_registration mr2 WHERE mr2.patient_id = mr.patient_id AND mr2.dept_sub_id = mr.dept_sub_id AND mr2.doctor_id = mr.doctor_id ORDER BY mr2.status ASC, mr2.create_time DESC LIMIT 1) AS slot, MIN(mr.status) AS status, (SELECT mr2.id FROM medical_registration mr2 WHERE mr2.patient_id = mr.patient_id AND mr2.dept_sub_id = mr.dept_sub_id AND mr2.doctor_id = mr.doctor_id ORDER BY mr2.status ASC, mr2.create_time DESC LIMIT 1) AS registrationId, (SELECT mrd.id FROM medical_record mrd INNER JOIN medical_registration mr3 ON mrd.registration_id = mr3.id WHERE mr3.patient_id = mr.patient_id AND mr3.dept_sub_id = mr.dept_sub_id AND mr3.doctor_id = mr.doctor_id LIMIT 1) AS medicalRecordId FROM medical_registration mr LEFT JOIN patient_user_info pi ON mr.patient_id = pi.id LEFT JOIN doctor d ON mr.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mr.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE 1 = 1
AND pi.name LIKE CONCAT('%',#{name},'%')
AND pi.sex = #{sex}
AND md.id = #{deptId}
AND mds.id = #{deptSubId}
AND d.id = #{doctorId}
AND mr.status = #{status}
GROUP BY mr.patient_id, mr.dept_sub_id, mr.doctor_id ORDER BY MAX(mr.create_time) DESC LIMIT #{start}, #{length}

SELECT mr.id AS registrationId, mr.date AS date, mr.slot AS slot, mr.status AS status, mr.payment_status AS paymentStatus, md.name AS deptName, mds.name AS deptSubName, d.name AS doctorName, mrd.diagnosis AS diagnosis, mrd.doctor_advice AS doctorAdvice, mrd.id AS medicalRecordId FROM medical_registration mr LEFT JOIN doctor d ON mr.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mr.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id LEFT JOIN medical_record mrd ON mrd.registration_id = mr.id WHERE mr.patient_id = #{patientId}
AND mr.dept_sub_id = #{deptSubId}
AND mr.doctor_id = #{doctorId}
ORDER BY mr.create_time DESC

SELECT mrd.id AS medicalRecordId, reg.id AS registrationId, reg.date AS visitDate, reg.slot AS slot, md.name AS department, mds.name AS deptSubName, d.name AS doctorName, mrd.chief_complaint AS chiefComplaintSummary, CASE WHEN EXISTS ( SELECT 1 FROM prescription p WHERE p.medical_record_id = mrd.id ) THEN 'PRESCRIPTION_READY' ELSE 'RECORD_READY' END AS status FROM medical_record mrd LEFT JOIN medical_registration reg ON mrd.registration_id = reg.id LEFT JOIN doctor d ON mrd.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mrd.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE mrd.patient_id = #{patientId}
AND reg.date >= #{startDate}
AND reg.date <= #{endDate}
ORDER BY reg.date DESC, reg.slot DESC, mrd.id DESC

SELECT p.id AS prescriptionId, p.medical_record_id AS medicalRecordId, reg.id AS registrationId, reg.date AS visitDate, reg.slot AS slot, md.name AS department, mds.name AS deptSubName, d.name AS doctorName, p.type AS type, p.status AS status, p.create_time AS createTime FROM prescription p LEFT JOIN medical_record mrd ON p.medical_record_id = mrd.id LEFT JOIN medical_registration reg ON mrd.registration_id = reg.id LEFT JOIN doctor d ON p.doctor_id = d.id LEFT JOIN medical_dept_sub mds ON mrd.dept_sub_id = mds.id LEFT JOIN medical_dept md ON mds.dept_id = md.id WHERE p.patient_id = #{patientId}
AND reg.date >= #{startDate}
AND reg.date <= #{endDate}
ORDER BY reg.date DESC, reg.slot DESC, p.id DESC

