UPDATE patient_user_info
name = #{name}, sex = #{sex}, pid = #{pid}, tel = #{tel}, birthday = #{birthday}, medical_history = #{medicalHistory}, allergy_history = #{allergyHistory}, family_history = #{familyHistory}, insurance_type = #{insuranceType},
WHERE id = #{id}
